settings.custom_liquid:
{%- comment -%}
  BAD Vinyl - v4.7.2 (Background Swap Only + MUCH Denser/Bigger Particles + Shooting Stars)
  Kept: ALL interactions, tilt, hover, click, audio, seek, spin, layout, typography.
  Changed: Ambient particle canvas now has a lot more particles, bigger particles, and shooting stars.
{%- endcomment -%}

<section id="bad-vinyl" aria-label="BAD Vinyl grid">
  <canvas class="bv-field" aria-hidden="true"></canvas>
  <div class="cinema-bars" aria-hidden="true"><span></span><span></span></div>
  <div class="bv-intro" aria-label="Album info">
    <span class="bv-intro__kicker">BAD MUSIC</span>
    <h1 class="bv-intro__title">2025</h1>
    <span class="bv-intro__sub">THE ALBUM &mdash; 12 TRACKS</span>
  </div>
  <div class="vinyl-grid" id="vinyl-grid"></div>
</section>

<style>
  #bad-vinyl{
    position:relative;min-height:100vh;min-height:100svh;width:100%;
    overflow:hidden;background:#000;isolation:isolate;color:#fff;
    padding:12px 12px 24px;text-align:center;

    --title-stroke-color: rgba(0,0,0,0.95);
    --title-stroke-width: 2.5px;
    --title-shadow: 0 0 0 var(--title-stroke-color),
      1px 0 0 var(--title-stroke-color), -1px 0 0 var(--title-stroke-color),
      0 1px 0 var(--title-stroke-color), 0 -1px 0 var(--title-stroke-color),
      1px 1px 0 var(--title-stroke-color), -1px 1px 0 var(--title-stroke-color),
      1px -1px 0 var(--title-stroke-color), -1px -1px 0 var(--title-stroke-color);
  }

  #bad-vinyl .bv-field{
    position:absolute;inset:0;width:100%;height:100%;
    pointer-events:none;z-index:0;opacity:1;
    mix-blend-mode:screen;
    transform:translateZ(0);
  }

  #bad-vinyl .cinema-bars,
  #bad-vinyl .vinyl-grid{position:relative;z-index:1;}

  @font-face{ font-family:'Impact'; src:local('Impact'), local('Impact Regular'); font-display:swap; }

  #bad-vinyl .vinyl-grid{
    display:grid !important;
    grid-template-columns:repeat(2,minmax(0,1fr)) !important;
    gap:26px;align-content:start;justify-items:center;
    min-height:calc(100svh - 64px);
  }
  @media (max-width:640px){
    #bad-vinyl .vinyl-grid{grid-template-columns:1fr !important;gap:10px;}
    #bad-vinyl{--title-stroke-width:3px;}
  }

  #bad-vinyl .vinyl-card{
    position:relative;isolation:isolate;text-align:center;width:100%;
    background:transparent;padding:10px 4px 14px;contain:paint;
    border-radius:10px;overflow:hidden;
  }

  #bad-vinyl .disc-wrap{position:relative;perspective:1400px;perspective-origin:50% 50%;margin-bottom:14px;z-index:1;}

  #bad-vinyl .vinyl-disc{
    --size: clamp(260px, min(28vh, 34vw), 560px);
    --spin-idle:18s; --spin-delay:0s; --press-scale:1;
    --angle:0deg;
    --rx:0deg; --ry:0deg;
    --tx:0px; --ty:0px;
    --ds-x:0px; --ds-y:18px;

    position:relative;width:var(--size);height:var(--size);margin:0 auto;border-radius:50%;
    border:2px solid #151515;background:#222;
    box-shadow:var(--ds-x) var(--ds-y) 48px rgba(0,0,0,.65), inset 0 0 0 6px #0b0b0b;
    cursor:pointer;will-change:transform,box-shadow;overflow:hidden;
    animation:vinylSpin var(--spin-idle) linear infinite var(--spin-delay);
    transform-style:preserve-3d;
    transform:translate3d(var(--tx),var(--ty),0) rotateX(var(--rx)) rotateY(var(--ry)) rotate(var(--angle)) scale(var(--press-scale));
    transition:box-shadow .12s ease, transform .06s ease;touch-action:manipulation;
  }
  #bad-vinyl .vinyl-disc:active{--press-scale:.985;}
  #bad-vinyl .vinyl-card.is-playing .vinyl-disc{
    box-shadow:var(--ds-x) calc(var(--ds-y) + 6px) 58px rgba(0,0,0,.7), inset 0 0 0 6px #0b0b0b;
  }

  #bad-vinyl .cd-art{
    position:absolute;inset:0;border-radius:50%;
    background-image:url('{{ 'cd.png' | file_url }}');
    background-position:center;background-repeat:no-repeat;background-size:100% 100%;
    z-index:0;filter:contrast(1.1);
    transform:translateZ(1px);
  }

  #bad-vinyl .sheen{
    position:absolute;inset:0;border-radius:50%;pointer-events:none;z-index:3;
    background:radial-gradient(circle at var(--lx,50%) var(--ly,50%), rgba(255,255,255,.26), rgba(255,255,255,0) 38%);
    mix-blend-mode:screen;filter:blur(.6px);
    transform:translateZ(3px);
  }

  #bad-vinyl .progress-ring{
    position:absolute;inset:0;border-radius:50%;z-index:2;pointer-events:none;
    background:conic-gradient(#ff33ff calc(var(--p,0) * 1%), transparent 0);
    opacity:.9;filter:drop-shadow(0 0 8px rgba(255,51,255,.35));
    -webkit-mask:radial-gradient(circle, transparent calc(50% - 8px), #000 calc(50% - 6px), #000 100%);
            mask:radial-gradient(circle, transparent calc(50% - 8px), #000 calc(50% - 6px), #000 100%);
    transform:translateZ(2px);
  }

  #bad-vinyl .vinyl-disc::after{
    content:"";position:absolute;inset:0;border-radius:50%;z-index:4;pointer-events:none;
    background:
      radial-gradient(circle at 50% 50%, rgba(0,0,0,.34) 0 3.2%, rgba(0,0,0,0) 3.3%),
      repeating-radial-gradient(rgba(255,255,255,.055) 0 2px, rgba(0,0,0,.05) 2px 4px);
    mix-blend-mode:overlay;
    transform:translateZ(4px);
  }
  #bad-vinyl .vinyl-center{
    position:absolute;left:50%;top:50%;width:12px;height:12px;
    transform:translate(-50%,-50%) translateZ(5px);border-radius:50%;
    background:#000;border:2px solid #222;z-index:5;
  }

  #bad-vinyl .badge{
    position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:48px;
    color:#fff;text-shadow:0 2px 8px rgba(0,0,0,.7);z-index:6;
    transition:opacity .15s ease, transform .15s ease;
    pointer-events:auto;cursor:pointer;user-select:none;background:none;border:none;
  }
  #bad-vinyl .badge.pause{opacity:0;}
  #bad-vinyl .vinyl-card.is-playing .badge.play{opacity:0;}
  #bad-vinyl .vinyl-card.is-playing .badge.pause{opacity:1;}
  #bad-vinyl .vinyl-disc:hover ~ .badge.play{transform:translate(-50%,-56%);}

  #bad-vinyl .vinyl-title{
    margin:6px 0 0;
    font-family:Impact,Haettenschweiler,'Arial Black',system-ui,sans-serif;
    font-weight:900;font-size:clamp(36px,7.5vw,98px);
    line-height:.9;letter-spacing:.01em;color:#f7f7f7;
    -webkit-text-stroke:var(--title-stroke-width) var(--title-stroke-color);
    text-shadow:var(--title-shadow);
    mix-blend-mode:normal;
    -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;
    text-rendering:geometricPrecision;
  }
  #bad-vinyl .vinyl-card.is-playing .vinyl-title{
    color:#ffeafd;
    text-shadow:var(--title-shadow), 0 0 10px rgba(255,51,255,.35), 0 0 18px rgba(88,101,242,.28);
  }

  .vinyl-artist{
    margin:6px 0 12px;
    font:800 clamp(26px,4.8vw,48px)/1 Impact,Haettenschweiler,'Arial Black',system-ui,sans-serif;
    color:#fff;letter-spacing:.01em;
    -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;
    text-rendering:geometricPrecision;
  }
  .vinyl-artist:empty{display:none;}

  .seek{position:relative;height:8px;margin:8px auto 10px;width:92%;background:#101010;border-radius:999px;border:1px solid #1b1b1b;cursor:pointer;}
  .seek .fill{position:absolute;left:0;top:0;height:100%;width:0%;border-radius:999px;background:linear-gradient(90deg,#ff33ff,#ffffff);box-shadow:0 0 12px rgba(255,51,255,.35);}
  .seek .knob{position:absolute;top:50%;transform:translate(-50%,-50%);width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:0 0 10px rgba(255,255,255,.6),0 0 12px rgba(255,51,255,.45);}
  .time-row{display:flex;align-items:center;justify-content:center;gap:8px;font-size:12px;color:#cfcfcf;}
  .time-row .dur{opacity:.8;}

  .is-disabled .vinyl-disc{cursor:not-allowed;filter:grayscale(1) contrast(.85) brightness(.9);}
  .soon{position:absolute;right:8px;top:8px;background:#1a1a1a;border:1px solid #2a2a2a;color:#bbb;font-size:10px;padding:2px 6px;border-radius:999px;letter-spacing:.08em;text-transform:uppercase;}

  .start-fx{position:absolute;inset:-10%;z-index:8;pointer-events:none;opacity:0;filter:saturate(135%) brightness(1.08);mix-blend-mode:screen;}
  .start-fx.run{animation:fxContainer 1200ms ease-out both;}
  .fx-bloom{position:absolute;inset:0;border-radius:50%;
    background:radial-gradient(circle, rgba(255,255,255,.9), rgba(255,255,255,0) 56%),
              radial-gradient(circle at 40% 60%, rgba(255,51,255,.8), transparent 62%),
              radial-gradient(circle at 70% 35%, rgba(57,255,20,.8), transparent 64%);
    transform:scale(.22);opacity:.95;filter:blur(.2px);
    animation:fxBloom calc(1200ms*.78) cubic-bezier(.2,.7,.2,1) forwards;
  }
  .fx-rings{position:absolute;inset:-2%;border-radius:50%;}
  .fx-ring{position:absolute;left:50%;top:50%;width:40%;height:40%;transform:translate(-50%,-50%) scale(.35);border-radius:50%;
    background:radial-gradient(circle, rgba(255,255,255,.9) 0 1px, transparent 2px), radial-gradient(circle, rgba(255,51,255,.7) 0, transparent 70%);
    -webkit-mask:radial-gradient(circle, transparent 46%, #000 48%, #000 100%); mask:radial-gradient(circle, transparent 46%, #000 48%, #000 100%);
    filter:blur(.3px);opacity:.95;animation:fxRing calc(1200ms*.9) cubic-bezier(.16,.8,.2,1) forwards;
  }
  .fx-ring.r2{width:56%;height:56%;animation-delay:40ms;background:radial-gradient(circle, rgba(255,255,255,.9) 0 1px, transparent 2px), radial-gradient(circle, rgba(57,255,20,.7) 0, transparent 70%);}
  .fx-ring.r3{width:72%;height:72%;animation-delay:80ms;}

  @keyframes vinylSpin{to{transform:rotate(360deg);}}
  @keyframes fxContainer{0%{opacity:1} 85%{opacity:1} 100%{opacity:0}}
  @keyframes fxBloom{0%{transform:scale(.22);opacity:.98;} 70%{transform:scale(2.4);opacity:.55;} 100%{transform:scale(2.76);opacity:0;filter:blur(1px);}}

  @media (prefers-reduced-motion: reduce){
    #bad-vinyl .vinyl-disc{--rx:0deg;--ry:0deg;--tx:0px;--ty:0px;animation:none;}
    #bad-vinyl .bv-field{display:none;}
  }

  @media (max-width: 640px){
    #bad-vinyl{padding-top:max(18px, calc(env(safe-area-inset-top, 0px) + 8px));}
    #bad-vinyl .vinyl-card{padding:6px 4px 8px;}
    #bad-vinyl .disc-wrap{margin-bottom:8px;}
    #bad-vinyl .seek{margin:6px auto 6px;}
    #bad-vinyl .time-row{margin-top:2px;}

    #bad-vinyl .vinyl-title{
      font-size:clamp(30px, 8.6vw, 56px);
      line-height:1.02;letter-spacing:.006em;
      -webkit-text-stroke:1.8px var(--title-stroke-color);
      text-shadow:
        0 0 0 var(--title-stroke-color),
        1px 0 0 var(--title-stroke-color), -1px 0 0 var(--title-stroke-color),
        0 1px 0 var(--title-stroke-color), 0 -1px 0 var(--title-stroke-color),
        .8px .8px 0 var(--title-stroke-color), -.8px .8px 0 var(--title-stroke-color),
        .8px -.8px 0 var(--title-stroke-color), -.8px -.8px 0 var(--title-stroke-color);
    }
    #bad-vinyl .vinyl-card.is-playing .vinyl-title{
      text-shadow:
        0 0 0 var(--title-stroke-color),
        1px 0 0 var(--title-stroke-color), -1px 0 0 var(--title-stroke-color),
        0 1px 0 var(--title-stroke-color), 0 -1px 0 var(--title-stroke-color),
        .8px .8px 0 var(--title-stroke-color), -.8px .8px 0 var(--title-stroke-color),
        .8px -.8px 0 var(--title-stroke-color), -.8px -.8px 0 var(--title-stroke-color),
        0 0 8px rgba(255,51,255,.22), 0 0 12px rgba(88,101,242,.20);
    }

    #bad-vinyl .vinyl-artist{
      font-size:clamp(18px, 4.4vw, 26px);
      line-height:1.08;letter-spacing:.004em;
      text-shadow:0 0 0 #000, 1px 0 0 #000, -1px 0 0 #000, 0 1px 0 #000, 0 -1px 0 #000;
    }
  }

  /* ===== V2: PAGE IDENTITY + VISUAL POLISH ===== */

  /* — Intro block — */
  .bv-intro{
    position:relative;z-index:1;
    text-align:center;
    padding:32px 16px 28px;
    margin-bottom:4px;
  }
  .bv-intro__kicker{
    display:block;
    font-family:Impact,Haettenschweiler,'Arial Black',system-ui,sans-serif;
    font-size:clamp(11px,1.8vw,14px);
    letter-spacing:0.32em;
    text-transform:uppercase;
    color:rgba(255,51,255,.45);
    margin-bottom:6px;
  }
  .bv-intro__title{
    font-family:Impact,Haettenschweiler,'Arial Black',system-ui,sans-serif;
    font-size:clamp(72px,14vw,140px);
    font-weight:900;
    line-height:.82;
    letter-spacing:.02em;
    color:#f7f7f7;
    margin:0;
    -webkit-text-stroke:2px rgba(0,0,0,0.9);
    text-shadow:
      0 0 0 rgba(0,0,0,0.9),
      0 0 40px rgba(255,51,255,.12),
      0 0 80px rgba(255,51,255,.06);
  }
  .bv-intro__sub{
    display:block;
    margin-top:10px;
    font-family:Impact,Haettenschweiler,'Arial Black',system-ui,sans-serif;
    font-size:clamp(10px,1.6vw,13px);
    letter-spacing:0.28em;
    text-transform:uppercase;
    color:rgba(255,255,255,.3);
  }
  /* Accent line below intro */
  .bv-intro::after{
    content:"";
    display:block;
    width:60px;
    height:2px;
    margin:18px auto 0;
    background:linear-gradient(90deg,transparent,rgba(255,51,255,.35),transparent);
    border-radius:1px;
  }

  /* — Grid polish — */
  #bad-vinyl .vinyl-grid{
    max-width:1200px;
    margin:0 auto;
    padding:0 8px;
  }

  /* — Card material treatment — */
  #bad-vinyl .vinyl-card{
    background:rgba(12,12,12,.6);
    border:1px solid rgba(255,255,255,.04);
    box-shadow:
      0 2px 8px rgba(0,0,0,.3),
      0 8px 24px rgba(0,0,0,.2);
    padding:14px 10px 16px;
    border-radius:12px;
    transition:border-color .2s ease, box-shadow .2s ease;
  }
  #bad-vinyl .vinyl-card.is-playing{
    border-color:rgba(255,51,255,.08);
    box-shadow:
      0 2px 8px rgba(0,0,0,.3),
      0 8px 24px rgba(0,0,0,.2),
      0 0 20px rgba(255,51,255,.04);
  }

  /* — Title refinement — */
  #bad-vinyl .vinyl-title{
    font-size:clamp(28px,6vw,72px);
    margin:8px 0 2px;
  }

  /* — Artist refinement — */
  #bad-vinyl .vinyl-artist{
    font-size:clamp(14px,2.8vw,22px);
    color:rgba(255,255,255,.65);
    margin:4px 0 10px;
    font-weight:400;
    letter-spacing:.04em;
  }

  /* — Seek bar refinement — */
  #bad-vinyl .seek{
    height:6px;
    width:88%;
    margin:10px auto 8px;
    background:#0c0c0c;
    border-color:rgba(255,255,255,.06);
  }
  #bad-vinyl .seek .fill{
    box-shadow:0 0 8px rgba(255,51,255,.25);
  }
  #bad-vinyl .seek .knob{
    width:12px;height:12px;
    box-shadow:0 0 6px rgba(255,255,255,.4),0 0 8px rgba(255,51,255,.3);
  }

  /* — Time row refinement — */
  #bad-vinyl .time-row{
    font-family:Impact,Haettenschweiler,'Arial Black',system-ui,sans-serif;
    font-size:11px;
    letter-spacing:.06em;
    color:rgba(255,255,255,.45);
    gap:6px;
  }

  /* — Section padding refinement — */
  #bad-vinyl{
    padding:0 16px 32px;
  }

  /* — Mobile adjustments for V2 — */
  @media (max-width:640px){
    .bv-intro{padding:22px 12px 20px;}
    .bv-intro__title{font-size:clamp(56px,16vw,90px);}
    .bv-intro::after{width:40px;margin-top:14px;}
    #bad-vinyl .vinyl-card{
      padding:10px 8px 12px;
      border-radius:10px;
    }
    #bad-vinyl .vinyl-title{
      font-size:clamp(24px,7vw,44px);
    }
    #bad-vinyl .vinyl-artist{
      font-size:clamp(12px,3.2vw,18px);
      margin:3px 0 8px;
    }
    #bad-vinyl{padding:0 10px 24px;}
  }

  /* ===== END V2 ===== */
</style>

<script>
/* ====== EDIT SONGS HERE ====== */
var BAD_TRACKS = [
  { title:"#AMERIKID",   artists:["6200 BPM (Prod. Bobby)"], src:"{{ '1.mp3' | file_url }}" },
  { title:"#ON",         artists:["REDD40 & MACCY (Prod. SWMG)"], src:"{{ '2.mp3' | file_url }}" },
  { title:"#VANHALEN",   artists:["LoyalGang Luke & Johnny AppleS33d (Prod. Parti)"], src:"{{ '3.mp3' | file_url }}" },
  { title:"#FREEVITALY", artists:["AZDONTCARE & Killa Goo$e (Prod. Parti)"], src:"{{ '4.mp3' | file_url }}" },
  { title:"#CHRISEAN",   artists:["LoafBoy Don"], src:"{{ '5.mp3' | file_url }}" },
  { title:"#FASHIONING", artists:["REDD40 (Prod. SWMG)"], src:"{{ '6.mp3' | file_url }}" },
  { title:"#KIDZYN",     artists:["TWINSTAR"], src:"{{ '7.mp3' | file_url }}" },
  { title:"#SUMMER OF THE HOODIE", artists:["Brent Pablo & Killa Goo$e"], src:"{{ '8.mp3' | file_url }}" },
  { title:"#KANDY",      artists:["KYS DEVI"], src:"{{ '9.mp3' | file_url }}" },
  { title:"#100PAIRS",   artists:["LoafBoy Don"], src:"{{ '10.mp3' | file_url }}" },
  { title:"#POISION",    artists:["FXJI (Prod. DW Destroyer)"], src:"{{ '11.mp3' | file_url }}" },
  { title:"#DIAMOND",    artists:["Nick Coleman (Prod. Parti)"], src:"{{ '12.mp3' | file_url }}" }
];
/* ============================= */

(function(){
  var sec = document.getElementById('bad-vinyl');
  var grid = document.getElementById('vinyl-grid');
  if(!sec || !grid) return;

  function enforceCols(){
    var cols = (window.innerWidth <= 640) ? 1 : 2;
    grid.style.display = 'grid';
    grid.style.gridTemplateColumns = 'repeat('+cols+', minmax(0,1fr))';
  }
  enforceCols();
  window.addEventListener('resize', enforceCols);

  var bars = sec.querySelector('.cinema-bars');
  function shake(){ sec.classList.remove('shake'); void sec.offsetWidth; sec.classList.add('shake'); setTimeout(function(){sec.classList.remove('shake');}, 500); }

  BAD_TRACKS.forEach(function(track, i){
    var card = document.createElement('article');
    card.className = 'vinyl-card';
    card.id = 'track-'+i;
    card.dataset.index = i;

    var discWrap = document.createElement('div'); discWrap.className='disc-wrap';
    var discBtn = document.createElement('button'); discBtn.className='vinyl-disc'; discBtn.type='button';
    discBtn.setAttribute('aria-label','Play '+(track.title||'Song')); discBtn.dataset.index = i;

    var cd = document.createElement('span'); cd.className='cd-art';
    var ring = document.createElement('span'); ring.className='progress-ring'; ring.style.setProperty('--p','0%');
    var center = document.createElement('span'); center.className='vinyl-center';
    var sheen = document.createElement('span'); sheen.className='sheen';

    var playB = document.createElement('button'); playB.className='badge play'; playB.type='button'; playB.setAttribute('aria-label','Play'); playB.textContent='▶'; playB.dataset.index = i;
    var pauseB = document.createElement('button'); pauseB.className='badge pause'; pauseB.type='button'; pauseB.setAttribute('aria-label','Pause'); pauseB.textContent='❚❚'; pauseB.dataset.index = i;

    var fx = document.createElement('div'); fx.className='start-fx';
    fx.innerHTML = '<div class="fx-bloom"></div><div class="fx-rings"><div class="fx-ring r1"></div><div class="fx-ring r2"></div><div class="fx-ring r3"></div></div>';

    discBtn.appendChild(cd); discBtn.appendChild(ring); discBtn.appendChild(center); discBtn.appendChild(sheen);
    discWrap.appendChild(discBtn); discWrap.appendChild(fx); discWrap.appendChild(playB); discWrap.appendChild(pauseB);

    var audio = document.createElement('audio'); audio.className='vinyl-audio'; audio.preload='metadata';
    if(track.src) audio.src = track.src;

    var title = document.createElement('h3'); title.className='vinyl-title'; title.textContent = track.title || 'Song';
    var artist = document.createElement('div'); artist.className='vinyl-artist';
    var artistList = Array.isArray(track.artists) ? track.artists : (track.artist ? [track.artist] : []);
    artist.textContent = artistList.join(', ');

    var seek = document.createElement('div'); seek.className='seek';
    var fill = document.createElement('span'); fill.className='fill';
    var knob = document.createElement('span'); knob.className='knob'; knob.style.left='0%';
    seek.appendChild(fill); seek.appendChild(knob);

    var timeRow = document.createElement('div'); timeRow.className='time-row';
    var el = document.createElement('span'); el.className='el'; el.textContent='0:00';
    var sep = document.createElement('span'); sep.textContent='•'; sep.style.opacity='.4';
    var dur = document.createElement('span'); dur.className='dur'; dur.textContent='0:00';
    timeRow.appendChild(el); timeRow.appendChild(sep); timeRow.appendChild(dur);

    card.appendChild(discWrap);
    card.appendChild(audio);
    card.appendChild(title);
    card.appendChild(artist);
    card.appendChild(seek);
    card.appendChild(timeRow);
    grid.appendChild(card);

    (function initDiscTilt(){
      if(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

      var rect = discWrap.getBoundingClientRect();
      var targetRX=0,targetRY=0,targetTX=0,targetTY=0;
      var curRX=0,curRY=0,curTX=0,curTY=0;
      var rafId=null, hover=false;

      var MAX_YAW=22, MAX_PITCH=18, MAX_SHIFT=22, EASE=0.16;

      function updateLighting(dx, dy){
        var lx = (50 + dx * 28).toFixed(1) + '%';
        var ly = (50 - dy * 28).toFixed(1) + '%';
        sheen.style.setProperty('--lx', lx);
        sheen.style.setProperty('--ly', ly);

        discBtn.style.setProperty('--ds-x', (dx * 12).toFixed(2) + 'px');
        discBtn.style.setProperty('--ds-y', (18 + Math.abs(dy) * 10).toFixed(2) + 'px');
      }

      function onMoveXY(clientX, clientY){
        var x = (clientX - rect.left) / rect.width;
        var y = (clientY - rect.top) / rect.height;
        var dx = Math.max(-1, Math.min(1, (x - 0.5) * 2));
        var dy = Math.max(-1, Math.min(1, (y - 0.5) * 2));

        targetRY = dx * MAX_YAW;
        targetRX = -dy * MAX_PITCH;
        targetTX = -dx * MAX_SHIFT;
        targetTY =  dy * MAX_SHIFT;
        updateLighting(dx, dy);
      }

      function animate(){
        curRX += (targetRX - curRX) * EASE;
        curRY += (targetRY - curRY) * EASE;
        curTX += (targetTX - curTX) * EASE;
        curTY += (targetTY - curTY) * EASE;

        discBtn.style.setProperty('--rx', curRX.toFixed(3) + 'deg');
        discBtn.style.setProperty('--ry', curRY.toFixed(3) + 'deg');
        discBtn.style.setProperty('--tx', curTX.toFixed(3) + 'px');
        discBtn.style.setProperty('--ty', curTY.toFixed(3) + 'px');

        if(hover || Math.abs(curRX)>0.05 || Math.abs(curRY)>0.05 || Math.abs(curTX)>0.05 || Math.abs(curTY)>0.05){
          rafId = requestAnimationFrame(animate);
        } else {
          rafId = null;
        }
      }

      function start(){ rect = discWrap.getBoundingClientRect(); hover = true; if(!rafId) rafId = requestAnimationFrame(animate); }
      function move(e){ onMoveXY(e.clientX, e.clientY); }
      function end(){ hover = false; targetRX=targetRY=targetTX=targetTY=0; if(!rafId) rafId = requestAnimationFrame(animate); }

      discWrap.addEventListener('pointerenter', start, {passive:true});
      discWrap.addEventListener('pointermove',  move,  {passive:true});
      discWrap.addEventListener('pointerleave', end,   {passive:true});


      window.addEventListener('resize', function(){ rect = discWrap.getBoundingClientRect(); }, {passive:true});
    })();

    card._rotationsPerTrack = Math.round(14 + Math.random()*16);
    discBtn.style.setProperty('--spin-idle', (14+Math.random()*16).toFixed(2)+'s');
    discBtn.style.setProperty('--spin-delay', (-Math.random()*20).toFixed(2)+'s');

    function fmt(t){ t=Math.max(0, t|0); var m=(t/60)|0, s=(t%60)|0; return m+':' + (s<10?'0':'')+s; }
    function updateTimeAndProgress(){
      var d=audio.duration||0, ct=audio.currentTime||0;
      if(d && isFinite(d)) dur.textContent = fmt(d);
      el.textContent = fmt(ct);
      var p = d? (ct/d)*100 : 0;
      fill.style.width = p+'%'; knob.style.left = p+'%'; ring.style.setProperty('--p', p+'%');
    }
    function startSpin(){
      discBtn.style.animation='none';
      var d=audio.duration||30;
      function loop(){
        var t=audio.currentTime||0;
        var angle=(t/d)*card._rotationsPerTrack*360;
        discBtn.style.setProperty('--angle', angle+'deg');
        updateTimeAndProgress();
        if(!audio.paused && !audio.ended){ card._rafId = requestAnimationFrame(loop); }
      }
      cancelAnimationFrame(card._rafId);
      card._rafId = requestAnimationFrame(loop);
    }
    function stopSpin(){
      cancelAnimationFrame(card._rafId); card._rafId=null;
      discBtn.style.animation='';
    }

    function hyperLaunch(){
      fx.classList.remove('run'); void fx.offsetWidth; fx.classList.add('run');
      if(bars){ bars.classList.remove('run'); void bars.offsetWidth; bars.classList.add('run'); }
      shake();
      setTimeout(function(){ fx.classList.remove('run'); }, 1280);
    }

    audio.addEventListener('loadedmetadata', updateTimeAndProgress);
    audio.addEventListener('timeupdate', updateTimeAndProgress);

    audio.addEventListener('play', function(){
      document.querySelectorAll('#bad-vinyl .vinyl-audio').forEach(function(a){ if(a!==audio){ a.pause(); } });
      card.classList.add('is-playing'); startSpin();
      if(!card._launched){ card._launched = true; hyperLaunch(); }
    });
    audio.addEventListener('pause', function(){ card.classList.remove('is-playing'); stopSpin(); });
    audio.addEventListener('ended', function(){ card.classList.remove('is-playing'); stopSpin(); });

    card.addEventListener('mouseenter', function(){
      if(audio && track.src && audio.readyState < 2 && audio.paused){ audio.preload='auto'; try{ audio.load(); }catch(e){} }
    });
  });

  sec.addEventListener('click', function(e){
    var hit = e.target.closest('.vinyl-disc, .badge');
    if(!hit || !sec.contains(hit)) return;

    var card = hit.closest('.vinyl-card');
    if(!card || card.classList.contains('is-disabled')) return;

    var audio = card.querySelector('.vinyl-audio');
    if(!audio) return;

    if(audio.paused){
      audio.play().catch(function(err){ console.warn('Play failed:', err); });
    } else {
      audio.pause();
    }
  }, { passive:true });

  sec.addEventListener('mousedown', function(e){
    var seek = e.target.closest('.seek'); if(!seek) return;
    var card = seek.closest('.vinyl-card'); var audio = card && card.querySelector('.vinyl-audio'); if(!audio) return;

    function seekTo(clientX){
      var r=seek.getBoundingClientRect();
      var x=Math.min(Math.max(0, clientX - r.left), r.width);
      var p=x/r.width;
      if(isFinite(audio.duration)) audio.currentTime=p*audio.duration;

      var fill = seek.querySelector('.fill');
      var knob = seek.querySelector('.knob');
      var pct = (audio.duration? (audio.currentTime/audio.duration)*100 : 0);
      fill.style.width = pct+'%'; knob.style.left = pct+'%';
      var ring = card.querySelector('.progress-ring'); if(ring) ring.style.setProperty('--p', pct+'%');
    }

    seekTo(e.clientX); e.preventDefault();
    function onMove(ev){ seekTo(ev.clientX); }
    function onUp(){ window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); }
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  });

  /* =========================
     Ambient background (MUCH denser + bigger + shooting stars)
  ========================= */
  (function initBadVinylAmbient(){
    var canvas = sec.querySelector('.bv-field');
    if(!canvas) return;

    var reduced = false;
    try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch(e){}
    if(reduced) return;

    var ctx = canvas.getContext('2d', { alpha:true });
    var w=0,h=0,dpr=1;

    var dust=[], floaters=[], shooters=[];
    var nextShooterAt=0, lastFrame=0;

    var COLORS = {
      white:{rgb:"255,255,255",hex:"#ffffff"},
      purple:{rgb:"255,51,255",hex:"#ff33ff"},
      blue:{rgb:"127,212,255",hex:"#7fd4ff"},
      yellow:{rgb:"255,211,74",hex:"#ffd34a"}
    };

    function clamp(v,min,max){return Math.min(max,Math.max(min,v));}
    function rand(min,max){return min+Math.random()*(max-min);}

    function densityScale(){
      var vw=window.innerWidth||1200;
      if(vw<520) return 0.28;
      if(vw<750) return 0.38;
      return 0.85;
    }

    var animationId=null;
    var isVisible=true;

    function resize(){
      var r=sec.getBoundingClientRect();
      w=Math.max(1,Math.floor(r.width));
      h=Math.max(1,Math.floor(r.height));
      dpr=1;
      canvas.width=Math.floor(w*dpr);
      canvas.height=Math.floor(h*dpr);
      canvas.style.width=w+"px";
      canvas.style.height=h+"px";
      ctx.setTransform(dpr,0,0,dpr,0,0);
    }

    function pickAccent(){
      var r=Math.random();
      if(r<0.40) return COLORS.purple;
      if(r<0.72) return COLORS.blue;
      return COLORS.yellow;
    }
    function pickDustColor(){ return (Math.random()<0.84)?COLORS.white:pickAccent(); }
    function pickFloaterColor(){ return (Math.random()<0.70)?COLORS.white:pickAccent(); }
    function pickFloaterKind(){
      var r=Math.random();
      if(r<0.015) return "blob";
      if(r<0.18) return "pill";
      return "dot";
    }
    function pickMeteorColor(){ return (Math.random()<0.78)?COLORS.white:pickAccent(); }

    function seedDust(){
      var area=w*h;
      var s=densityScale();
      var vw=window.innerWidth||1200;
      var count;
      if(vw<520) count=Math.round(clamp((area/600)*s, 120, 300));
      else if(vw<750) count=Math.round(clamp((area/500)*s, 160, 450));
      else count=Math.round(clamp((area/400)*s, 400, 800));
      dust=new Array(count);

      for(var i=0;i<count;i++){
        var color=pickDustColor();
        var isAccent=(color!==COLORS.white);

        var vx=rand(-0.026,0.026);
        var vy=rand(-0.020,0.020);
        var tw=rand(0.28,1.05);
        var ph=rand(0,Math.PI*2);

        var a0=isAccent?rand(0.18,0.40):rand(0.05,0.15);
        var size=isAccent?rand(1.8,3.2):((Math.random()<0.78)?rand(1.2,2.2):rand(2.2,3.0));

        dust[i]={x:rand(0,w),y:rand(0,h),vx:vx,vy:vy,color:color,isAccent:isAccent,a0:a0,size:size,tw:tw,ph:ph};
      }
    }

    function seedFloaters(){
      var area=w*h;
      var s=densityScale();
      var vw=window.innerWidth||1200;
      var count;
      if(vw<520) count=Math.round(clamp((area/7000)*s, 40, 100));
      else if(vw<750) count=Math.round(clamp((area/5000)*s, 50, 130));
      else count=Math.round(clamp((area/1800)*s, 200, 400));
      floaters=new Array(count);

      for(var i=0;i<count;i++){
        var kind=pickFloaterKind();
        var color=pickFloaterColor();
        var isAccent=(color!==COLORS.white);

        var vx=rand(-0.14,0.14);
        var vy=rand(-0.12,0.12);
        var tw=rand(0.38,1.25);
        var ph=rand(0,Math.PI*2);

        var a0=isAccent?rand(0.44,0.80):rand(0.16,0.42);
        if(kind==="blob") a0*=0.75;
        if(kind==="pill") a0*=0.9;

        var p={x:rand(0,w),y:rand(0,h),vx:vx,vy:vy,kind:kind,color:color,isAccent:isAccent,a0:a0,tw:tw,ph:ph};

        if(kind==="dot"){
          p.r=isAccent?rand(3.0,6.0):((Math.random()<0.65)?rand(1.8,3.2):rand(3.2,5.0));
        } else if(kind==="pill"){
          p.pw=rand(10,28);
          p.phh=rand(2.4,5.0);
          p.rot=rand(-0.7,0.7);
        } else {
          p.br=rand(7,14);
        }
        if(isAccent) p.glowSize=rand(7,16);

        floaters[i]=p;
      }
    }

    function drawRoundRect(x,y,ww,hh,rr){
      var r=Math.min(rr,ww/2,hh/2);
      ctx.beginPath();
      ctx.moveTo(x+r,y);
      ctx.lineTo(x+ww-r,y);
      ctx.quadraticCurveTo(x+ww,y,x+ww,y+r);
      ctx.lineTo(x+ww,y+hh-r);
      ctx.quadraticCurveTo(x+ww,y+hh,x+ww-r,y+hh);
      ctx.lineTo(x+r,y+hh);
      ctx.quadraticCurveTo(x,y+hh,x,y+hh-r);
      ctx.lineTo(x,y+r);
      ctx.quadraticCurveTo(x,y,x+r,y);
      ctx.closePath();
      ctx.fill();
    }

    function scheduleNextShooter(now){ nextShooterAt = now + rand(1200, 3400); } // more frequent

    function spawnShooter(now){
      var fromLeft = Math.random() < 0.5;
      var depth = rand(0.55, 1.0);

      var y = rand(h*0.08, h*0.92);
      var x = fromLeft ? -rand(80,160) : (w + rand(80,160));
      var ang = fromLeft ? rand(-0.42,0.42) : rand(Math.PI-0.42, Math.PI+0.42);

      var speed = rand(820, 1620) * (0.70 + depth*0.45);
      var life = rand(0.65, 1.20);
      var color = pickMeteorColor();
      var tail = rand(150, 300) * depth;

      shooters.push({
        x:x,y:y,vx:Math.cos(ang)*speed,vy:Math.sin(ang)*speed,
        t:0,life:life,depth:depth,tail:tail,w:rand(1.2,2.6)*depth,color:color
      });

      scheduleNextShooter(now);
    }

    function drawShooter(s){
      var p=clamp(s.t/s.life,0,1);
      var fadeIn=Math.pow(clamp(p/0.12,0,1),0.7);
      var fadeOut=1-Math.pow(clamp((p-0.45)/0.55,0,1),1.8);
      var a=fadeIn*fadeOut;
      if(a<0.01) return;

      var spd=Math.sqrt(s.vx*s.vx + s.vy*s.vy) || 1;
      var dx=s.vx/spd, dy=s.vy/spd;
      var tl=s.tail*(0.65+0.35*a);
      var tx=s.x - dx*tl, ty=s.y - dy*tl;

      ctx.save();
      ctx.lineCap="round";

      var g1=ctx.createLinearGradient(tx,ty,s.x,s.y);
      g1.addColorStop(0,"rgba("+s.color.rgb+",0)");
      g1.addColorStop(1,"rgba("+s.color.rgb+","+(0.55*a).toFixed(4)+")");
      ctx.strokeStyle=g1;
      ctx.lineWidth=s.w*4.8;
      ctx.beginPath(); ctx.moveTo(tx,ty); ctx.lineTo(s.x,s.y); ctx.stroke();

      var g2=ctx.createLinearGradient(tx,ty,s.x,s.y);
      g2.addColorStop(0,"rgba("+s.color.rgb+",0)");
      g2.addColorStop(1,"rgba(255,255,255,"+(0.85*a).toFixed(4)+")");
      ctx.strokeStyle=g2;
      ctx.lineWidth=s.w*2.0;
      ctx.beginPath();
      ctx.moveTo(tx+(s.x-tx)*0.18, ty+(s.y-ty)*0.18);
      ctx.lineTo(s.x,s.y);
      ctx.stroke();

      var headR=s.w*2.2;
      ctx.shadowBlur=14*s.depth;
      ctx.shadowColor=s.color.hex;

      var hg=ctx.createRadialGradient(s.x,s.y,0,s.x,s.y,headR*3.0);
      hg.addColorStop(0,"rgba(255,255,255,"+(0.95*a).toFixed(4)+")");
      hg.addColorStop(0.25,"rgba("+s.color.rgb+","+(0.70*a).toFixed(4)+")");
      hg.addColorStop(1,"rgba("+s.color.rgb+",0)");
      ctx.fillStyle=hg;
      ctx.beginPath(); ctx.arc(s.x,s.y,headR*3.0,0,Math.PI*2); ctx.fill();

      ctx.restore();
      ctx.shadowBlur=0; ctx.shadowColor="transparent";
    }

    function step(ts){
      if(!isVisible){ animationId=null; return; }
      var now = ts || performance.now();
      var dt = lastFrame ? clamp((now-lastFrame)/1000, 0.001, 0.05) : (1/60);
      lastFrame = now;
      var time = now * 0.001;

      ctx.clearRect(0,0,w,h);
      ctx.globalCompositeOperation="lighter";
      ctx.shadowBlur=0; ctx.shadowColor="transparent";

      for(var i=0;i<dust.length;i++){
        var d=dust[i];
        d.x+=d.vx; d.y+=d.vy;
        if(d.x<-2) d.x=w+2; if(d.x>w+2) d.x=-2;
        if(d.y<-2) d.y=h+2; if(d.y>h+2) d.y=-2;

        var twk=0.70 + 0.30*Math.sin(time*d.tw + d.ph);
        var a=d.a0*twk;

        ctx.shadowBlur=0;

        ctx.fillStyle="rgba("+d.color.rgb+","+a.toFixed(3)+")";
        ctx.fillRect(d.x-d.size*0.5, d.y-d.size*0.5, d.size, d.size);
      }

      for(var j=0;j<floaters.length;j++){
        var p=floaters[j];
        p.x+=p.vx; p.y+=p.vy;
        if(p.x<-25) p.x=w+25; if(p.x>w+25) p.x=-25;
        if(p.y<-25) p.y=h+25; if(p.y>h+25) p.y=-25;

        var tw2=0.65 + 0.35*Math.sin(time*p.tw + p.ph);
        var a2=p.a0*tw2;

        if(p.isAccent && p.glowSize){ ctx.shadowBlur=p.glowSize*tw2; ctx.shadowColor=p.color.hex; }
        else { ctx.shadowBlur=0; ctx.shadowColor="transparent"; }

        ctx.fillStyle="rgba("+p.color.rgb+","+a2.toFixed(3)+")";

        if(p.kind==="dot"){
          ctx.beginPath(); ctx.arc(p.x,p.y,p.r,0,Math.PI*2); ctx.fill();
        } else if(p.kind==="pill"){
          ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.rot);
          drawRoundRect(-p.pw/2, -p.phh/2, p.pw, p.phh, p.phh/2);
          ctx.restore();
        } else {
          var r=p.br;
          ctx.beginPath();
          ctx.arc(p.x,p.y,r,0,Math.PI*2);
          ctx.arc(p.x+r*0.5, p.y-r*0.2, r*0.7, 0, Math.PI*2);
          ctx.arc(p.x-r*0.4, p.y+r*0.15, r*0.6, 0, Math.PI*2);
          ctx.fill();
        }
      }

      if(!nextShooterAt) scheduleNextShooter(now);
      if(now >= nextShooterAt) spawnShooter(now);

      for(var k=shooters.length-1;k>=0;k--){
        var s=shooters[k];
        s.t += dt;
        s.x += s.vx*dt;
        s.y += s.vy*dt;

        drawShooter(s);

        var m=560;
        if(s.t>=s.life || s.x<-m || s.x>w+m || s.y<-m || s.y>h+m){
          shooters.splice(k,1);
        }
      }

      ctx.globalCompositeOperation="source-over";
      ctx.shadowBlur=0; ctx.shadowColor="transparent";
      animationId=requestAnimationFrame(step);
    }

    resize();
    seedDust();
    seedFloaters();
    animationId=requestAnimationFrame(step);

    /* ---- Offscreen cancel/restart (IO) ---- */
    var bvIO=new IntersectionObserver(function(entries){
      var vis=entries[0].isIntersecting;
      isVisible=vis;
      if(vis){
        lastFrame=0;
        if(!animationId) animationId=requestAnimationFrame(step);
      } else {
        if(animationId){ cancelAnimationFrame(animationId); animationId=null; }
      }
    }, {threshold:0});
    bvIO.observe(sec);

    if('ResizeObserver' in window){
      var ro=new ResizeObserver(function(){
        resize(); seedDust(); seedFloaters();
        shooters.length=0; nextShooterAt=0; lastFrame=0;
      });
      ro.observe(sec);
    } else {
      window.addEventListener('resize', function(){
        resize(); seedDust(); seedFloaters();
        shooters.length=0; nextShooterAt=0; lastFrame=0;
      }, {passive:true});
    }
  })();
})();
</script>
